198	export function buildDateCursorClause(
199	  cursor: DateCursor | null,
200	  occurredAtColumn: string,
201	  idColumn: string,
202	  baseParamIndex: number
203	): { sql: string; params: unknown[] } {
204	  if (!cursor) return { sql: '', params: [] };
205	
206	  const occurredAtParam = `$${baseParamIndex}::timestamptz`;
207	  const idParam = `$${baseParamIndex + 1}::bigint`;
208	
209	  if (cursor.direction === 'before') {
210	    return {
211	      sql: `AND (${occurredAtColumn} < ${occurredAtParam} OR (${occurredAtColumn} = ${occurredAtParam} AND ${idColumn} < ${idParam}))`,
212	      params: [cursor.occurredAtIso, cursor.id],
213	    };
214	  }
215	
216	  return {
217	    sql: `AND (${occurredAtColumn} > ${occurredAtParam} OR (${occurredAtColumn} = ${occurredAtParam} AND ${idColumn} > ${idParam}))`,
218	    params: [cursor.occurredAtIso, cursor.id],
219	  };
220	}
