159	export async function listAgentThreads(args: {
160		agentId: string;
161		organizationId?: string;
162		userId: string;
163		/** "user" (default): only the requesting user's app threads. "all": every
164		 *  conversation for the agent across platforms (Slack, Telegram, …). */
165		scope?: "user" | "all";
166	}): Promise<AgentThreadSummary[]> {
167		const { agentId, organizationId, userId, scope = "user" } = args;
168		// No org → no tenant scope → nothing to list from the (org-keyed) entity.
169		if (!organizationId) return [];
170	
171		const byKey = new Map<string, AgentThreadSummary>();
172	
173		// Owned + platform conversations come from the `conversations` entity — the
174		// single listing source. This replaces the old
175		// `DISTINCT ON (conversation_id) FROM agent_transcript_snapshot` derive path
176		// AND the workspace-directory scan.
177		const rows = await listConversations({
178			organizationId,
179			agentId,
180			scope,
181			userId,
182		});
183	
184		// Platform ("all" scope) rows are ACL-gated: a platform conversation is only
185		// listed if its channel is in the agent's bound channels AND (for ACL-graphed
186		// connections) the requester is a member — so a user never sees a channel
187		// transcript they can't read.
188		let channelVis: ChannelVisibility | null = null;
189		if (scope === "all") {
190			channelVis = await resolveChannelVisibility(getDb(), {
191				organizationId,
192				agentId,
193				userId,
194			});
195		}
196	
197		for (const row of rows) {
198			const at = row.lastActivityAt.getTime();
199			const createdAt = row.createdAt.getTime();
200			if (row.kind === "owned") {
201				// Routable id is STORED (`thread_id`), never re-parsed out of the id
202				// string. The migration trigger also covers writes from an old server
203				// between the pre-upgrade migration and deployment replacement.
204				const threadId = row.threadId;
205				if (!threadId || !isSafeThreadId(threadId) || byKey.has(threadId)) {
206					continue;
207				}
208				byKey.set(threadId, {
209					id: threadId,
210					title: row.title ?? `Conversation ${byKey.size + 1}`,
211					createdAt,
212					updatedAt: at,
213					platform: "web",
214					conversationId: row.conversationId,
215				});
216			} else if (row.kind === "platform") {
217				// One entry per conversationId — that's the whole identity of a platform
218				// conversation (the connection that delivered it is routing, not identity;
219				// a reconnect changes it without changing the conversation). The ACL and
220				// transcript read address it by conversationId alone, consistent with this.
221				//
222				// isConversationVisible extracts platform:channel from the id, so an
223				// opaque/no-colon platform id fails closed (unlisted) — same as the prior
224				// path, which only ever listed `LIKE '%:%'` platform ids. Failing closed
225				// is safe; the same-channel-across-two-workspaces (Grid) case is likewise
226				// handled by isConversationVisible failing closed on team ambiguity.
227				if (byKey.has(row.conversationId)) continue;
228				if (channelVis && !isConversationVisible(row.conversationId, channelVis)) {
229					continue;
230				}
231				byKey.set(row.conversationId, {
232					id: row.conversationId,
233					title: row.title ?? row.conversationId,
234					createdAt,
235					updatedAt: at,
236					// Label from the EXPLICIT stored platform, not by parsing the id — an
237					// opaque/no-colon platform id (e.g. gchat spaces_A_threads_B) would
238					// otherwise mislabel as "web".
239					platform: row.platform,
240					conversationId: row.conversationId,
241				});
242			}
243		}
244	
245		// Watcher activity stays DERIVED from transcript snapshots — one entry per
246		// WATCHER (not per run), its latest run time + name, so the activity panel
247		// can route to the watcher's page. Watcher runs deliberately get no
248		// `conversations` row (their id is globally unique and downstream correlation
249		// relies on the raw `..._watcher_<id>_run_<id>` shape).
250		if (scope === "all") {
251			const sql = getDb();
252			const watcherRows = await sql<{
253				watcher_id: number;
254				name: string | null;
255				last_at: Date;
256			}>`
257	      SELECT w.id AS watcher_id, w.name, mx.last_at
258	      FROM (
259	        SELECT (regexp_match(conversation_id, '_watcher_([0-9]+)_run_'))[1]::int AS watcher_id,
260	               max(created_at) AS last_at
261	        FROM public.agent_transcript_snapshot
262	        WHERE organization_id = ${organizationId}
263	          AND agent_id = ${agentId}
264	          AND terminal_status = 'completed'
265	          AND conversation_id LIKE '%\\_watcher\\_%\\_run\\_%'
266	        GROUP BY 1
267	      ) mx
268	      JOIN public.watchers w ON w.id = mx.watcher_id
269	    `;
270			for (const row of watcherRows) {
271				const key = `watcher_${row.watcher_id}`;
272				const at = row.last_at.getTime();
273				byKey.set(key, {
274					id: key,
275					title: row.name ?? `Behavior ${row.watcher_id}`,
276					createdAt: at,
277					updatedAt: at,
278					platform: "behavior",
279					conversationId: key,
280					behaviorId: row.watcher_id,
281				});
282			}
283		}
284	
285		return [...byKey.values()].sort((a, b) => b.updatedAt - a.updatedAt);
286	}
