132	async function findCurrentEventByOrigin(
133	  sql: DbClient,
134	  params: InsertEventParams
135	): Promise<
136	  | {
137	      id: number;
138	      title: string | null;
139	      payload_text: string | null;
140	      payload_type: string;
141	      payload_data: Record<string, unknown>;
142	      payload_template: Record<string, unknown> | null;
143	      attachments: unknown[];
144	      author_name: string | null;
145	      source_url: string | null;
146	      occurred_at: string | null;
147	      semantic_type: string;
148	      origin_type: string | null;
149	      metadata: Record<string, unknown>;
150	      score: number | null;
151	      origin_parent_id: string | null;
152	      interaction_type: string;
153	      interaction_status: string | null;
154	      interaction_input_schema: Record<string, unknown> | null;
155	      interaction_input: Record<string, unknown> | null;
156	      interaction_output: Record<string, unknown> | null;
157	      interaction_error: string | null;
158	    }
159	  | undefined
160	> {
161	  if (!params.connectionId || !params.originId) return undefined;
162	
163	  const rows = await sql`
164	    SELECT e.id, e.title, e.payload_text, e.payload_type, e.payload_data, e.payload_template,
165	           e.attachments, e.author_name, e.source_url, e.occurred_at, e.semantic_type, e.origin_type,
166	           e.metadata, e.score, e.origin_parent_id, e.interaction_type, e.interaction_status,
167	           e.interaction_input_schema, e.interaction_input, e.interaction_output, e.interaction_error
168	    FROM events e
169	    WHERE e.organization_id = ${params.organizationId}
170	      AND e.connection_id = ${params.connectionId}
171	      AND e.origin_id = ${params.originId}
172	      AND NOT EXISTS (
173	        SELECT 1 FROM events newer WHERE newer.supersedes_event_id = e.id
174	      )
175	    ORDER BY e.created_at DESC, e.id DESC
176	    LIMIT 1
177	  `;
178	
179	  return rows[0] as any;
180	}
