182	function isSemanticallyEqual(
183	  existing: NonNullable<Awaited<ReturnType<typeof findCurrentEventByOrigin>>>,
184	  params: InsertEventParams
185	): boolean {
186	  return (
187	    (existing.title ?? null) === (params.title ?? null) &&
188	    (existing.payload_text ?? null) === (params.content ?? null) &&
189	    existing.payload_type === (params.payloadType ?? 'text') &&
190	    stableJson(existing.payload_data ?? {}) === stableJson(params.payloadData ?? {}) &&
191	    stableJson(existing.payload_template ?? null) === stableJson(params.payloadTemplate ?? null) &&
192	    stableJson(existing.attachments ?? []) === stableJson(params.attachments ?? []) &&
193	    (existing.author_name ?? null) === (params.authorName ?? null) &&
194	    (existing.source_url ?? null) === (params.sourceUrl ?? null) &&
195	    normalizedTimestamp(existing.occurred_at ?? null) ===
196	      normalizedTimestamp(params.occurredAt ?? null) &&
197	    existing.semantic_type === params.semanticType &&
198	    (existing.origin_type ?? null) === (params.originType ?? null) &&
199	    stableJson(existing.metadata ?? {}) === stableJson(params.metadata ?? {}) &&
200	    Number(existing.score ?? 0) === Number(params.score ?? 0) &&
201	    (existing.origin_parent_id ?? null) === (params.parentOriginId ?? null) &&
202	    existing.interaction_type === (params.interactionType ?? 'none') &&
203	    (existing.interaction_status ?? null) === (params.interactionStatus ?? null) &&
204	    stableJson(existing.interaction_input_schema ?? null) ===
205	      stableJson(params.interactionInputSchema ?? null) &&
206	    stableJson(existing.interaction_input ?? null) ===
207	      stableJson(params.interactionInput ?? null) &&
208	    stableJson(existing.interaction_output ?? null) ===
209	      stableJson(params.interactionOutput ?? null) &&
210	    (existing.interaction_error ?? null) === (params.interactionError ?? null)
211	  );
212	}
213	
214	async function upsertEmbedding(
215	  eventId: number,
216	  embedding: number[] | null | undefined,
217	  embeddingModel: string | null | undefined,
218	  sql: DbClient = getDb()
219	): Promise<void> {
220	  if (!embedding || embedding.length === 0) return;
221	  // An unstamped vector is unusable — search scopes vector comparison to the
222	  // configured model — so skip it and let the embed backfill produce a properly
223	  // stamped one.
224	  if (!embeddingModel) return;
225	  const vectorLiteral = `[${embedding.join(',')}]`;
226	  // Replace this (event, model)'s chunk set with a single chunk-0 row:
227	  // delete-then-insert scoped to the model so old/new models can coexist
228	  // during a zero-downtime swap (PK is event_id + embedding_model + chunk_index).
229	  await sql`DELETE FROM event_embeddings WHERE event_id = ${eventId} AND embedding_model = ${embeddingModel}`;
230	  await sql`
231	    INSERT INTO event_embeddings (event_id, chunk_index, embedding, embedding_model)
232	    VALUES (${eventId}, 0, ${vectorLiteral}::vector, ${embeddingModel})
233	  `;
234	}
235	
236	function isEventsClientIdForeignKeyViolation(error: unknown): boolean {
237	  const err = error as {
238	    code?: unknown;
239	    constraint?: unknown;
240	    constraint_name?: unknown;
241	    message?: unknown;
242	  };
243	  if (err?.code !== '23503') return false;
244	  return (
245	    err.constraint === 'events_client_id_fkey' ||
246	    err.constraint_name === 'events_client_id_fkey' ||
247	    (typeof err.message === 'string' && err.message.includes('events_client_id_fkey'))
248	  );
249	}
