501	// Change Event (fire-and-forget audit trail)
502	// ============================================
503	
504	interface ChangeEventParams {
505	  entityIds: number[];
506	  organizationId: string;
507	  title: string;
508	  content: string;
509	  metadata: Record<string, unknown>;
510	  createdBy?: string | null;
511	  clientId?: string | null;
512	}
