239	  // Per-invocation correlation id (lobu#2051 Item 2). Distinct from the
240	  // background-run `run_id` (a bigint on the runs table) — this identifies a
241	  // single tool call so a failure can be traced across logs/audit/response.
242	  const callId = randomUUID();
243	
244	  const runHandler = () =>
245	    trackMCPToolCall(toolName, args, () => tool.handler(args, env, toolContext));
246	
247	  try {
