							{group.clientIds.length > 1 ? (
								<span className="shrink-0 rounded-md bg-muted px-1.5 py-0.5 text-[10px] font-medium text-muted-foreground">
									{group.clientIds.length} registrations
								</span>
							) : null}
							{group.firstParty ? (
								<span className="shrink-0 rounded-md bg-muted px-1.5 py-0.5 text-[10px] font-medium uppercase tracking-wide text-muted-foreground">
									Lobu
								</span>
							) : null}
						</div>
						<div className="truncate text-xs text-muted-foreground">
							{group.linkedUser ? `${group.linkedUser} · ` : ""}
